          "detail": "二月福建沙县佃农邓茂七倡率乡民拒纳地主正租之外苛索之“冬牲”薪米，拒捕杀县巡检，自称“铲平王”（旋改延平王），设官属聚众十余万，连破二十余县、围攻延平府并斩明都指挥范真，与处州叶宗留矿徒军遥相声援。三月靖远伯王骥复督十三万大军第三次征讨云南麓川思机发，逾孟养鬼哭山破其栅寨，耗费军饷巨亿而精锐顿于西南。七月黄河在开封荣泽大决口灌没城池，北冲张秋溃会通河运道。",
