          "title": "土木堡之变：王振挟明英宗五十万大军亲征瓦剌全军覆没，英宗被俘北狩",
          "detail": "瓦剌太师也先遣使二千余人虚报三千人入贡索赏，王振大减马价五分之四激怒也先；七月也先统铁骑分四路南侵破大同阳和堡。王振不顾兵部尚书邝埜、侍郎于谦谏阻，挟二十三岁的明英宗仓促发京营二十余万（号五十万）冒雨出居庸关亲征；八月抵大同闻前线尸积塞野，惧而东撤，王振欲邀驾临幸其蔚州故里旋恐大军践踏庄稼复折回宣府。八月辛酉退驻怀来城西二十里无水高地“土木堡”，壬戌（十五日）被也先铁骑四面合围断绝水源；癸亥瓦剌诈退议和，饥渴移营取水的明军遭四面突击大溃，死者数十万，英国公张辅、成国公朱勇、尚书邝埜与王佐等五十余名重臣殉难，护卫将军樊忠以铁锤怒击王振毙之，明英宗下马盘膝端坐被俘（史称“土木堡之变”，明朝由攻转守之历史转折点）。",
