          "detail": "八月甲子土木败报抵京，侍讲徐珵（后改名有贞）妄言星象倡议南迁南京，兵部左侍郎于谦厉声抗言：“言南迁者，可斩也！京师天下根本，一动则大事去矣，独不见宋南渡事乎！”孙皇太后遂命郕王朱祁钰监国、擢于谦为兵部尚书，午门朝审时廷臣当场捶毙王振死党锦衣卫指挥马顺；九月癸未郕王即皇帝位（明代宗景帝），遥尊英宗为太上皇以绝也先挟持勒索之念。十月也先挟英宗突破紫荆关直逼北京城下，于谦与石亨统调集之二十二万勤王兵背城列阵九门外并亲自披甲镇守德胜门，预伏神机火铳与短兵于空屋，诱歼也先弟孛罗、平章卯那孩及精骑万余，孙镗、范广复破敌于西直门与彰义门，激战五昼夜迫也先拔营遁出塞外，保住大明半壁与京师根基（北京保卫战）。同年二月宁阳侯陈懋攻杀邓茂七平福建民变，八月广州黄萧养起义围广州。",
