          "detail": "六月（一作八月），户部尚书叶淇奏准变通洪武以来商人运粮九边仓场换领盐引之“开中纳粟”旧制，改为准许盐商直接在两淮等都转运盐使司缴纳白银（每引输银三至四钱）领引行盐，白银解户部太仓再分发各边充饷（史称“叶淇变法”或开中折色）。此举使国家太仓盐课银骤增至百万两，催生扬州两淮徽商、晋商巨额货币资本积聚，但亦致北方沿边商屯渐趋荒废。",
