          "detail": "游牧伏尔加河下游百四十余年之卫拉特蒙古土尔扈特部不堪沙俄征调重兵与改教压迫，在二十九岁首领渥巴锡汗率领下于年初聚众十七万焚宫东归故土；冲破哥萨克追击、风雪荒漠与瘟疫，付出牺牲过半之惨烈代价，历时半年行程万余里，六月抵伊犁河畔归附清朝。九月乾隆帝于承德避暑山庄隆重接见渥巴锡，封卓哩克图汗，拨库银二十万两及巴音布鲁克等水草丰美牧地妥善安置，御撰《土尔扈特全部归顺记》与《优恤土尔扈特部众记》立碑普陀宗乘之庙。同年夏大小金川土司复叛，第二次金川之役爆发。",
