          "detail": "正月戊申朔，八十六岁的清高宗乾隆帝以在位不敢逾祖父康熙六十一年之数，御太和殿亲授宝玺传位于皇太子颙琰（清仁宗嘉庆帝），自称太上皇帝，皇极殿再设五千人“千叟宴”，然军国机务与用人批折仍由太上皇训政、和珅居中传旨，大内仍并行书乾隆六十一年。就在归政同月，因官吏借查教敲诈激变，湖北宜都张正谟、襄阳齐林妻王聪儿与姚之富率白莲教众起义，四川达州徐天德、王三槐旋即响应，席卷鄂、川、陕、豫、甘五省历时九载之“川楚白莲教大起义”全面爆发，清王朝由此由盛转衰。",
