          "detail": "北方天理教（八卦教）首领林清、李文成密约九月十五日起义：河南滑县李文成因事泄于九月初七日提前起事占滑县；九月十五日（癸酉）午时，林清遣教众二百人由太监刘得财等内应引导，乘嘉庆帝自热河返京在途之机，分自东华门、西华门突入大内直扑隆宗门（门匾至今留箭头遗迹），在宫读书之皇次子智亲王绵宁（后道光帝）亲执鸟枪射毙攀墙教徒二人，火器营入援激战两日歼俘入宫教众。嘉庆帝回銮震骇痛颁《遇变罪己诏》，叹为“汉、唐、宋、明未有之事”；十二月陕甘总督那彦成、杨遇春攻克滑县（李文成先于司寨自焚死）。",
