          "detail": "五月（公历6月下旬），英国政府在议会通过军费案后，派遣全权代表懿律（George Elliot）与查理·义律率领海军舰船四十余艘（含铁壳明轮蒸汽炮舰“复仇女神号”等）及陆军四千人驶抵广东海面，宣布封锁珠江口，“第一次鸦片战争”正式爆发。因林则徐、关天培于虎门横档岛严设排链炮台无隙可乘，英舰主力遂北犯厦门不逞，六月（公历7月5—6日）炮轰攻陷毫无戒备之浙江舟山定海县城（知县姚怀祥投水殉国），中国自此步入抵御西方列强侵略之近代历史时期。",
