          "detail": "五月（公历6月16日）英舰猛攻长江门户吴淞炮台，年近七旬之江南提督陈化成独守西炮台发炮重创英舰后力战捐躯，上海、镇江相继失守（镇江驻防副都统海龄率旗兵巷战殉难）并截断大运河，七月英舰列炮南京下关江面。七月二十四日（公历8月29日），清钦差大臣耆英、伊里布于英舰“皋华丽号”签署中国近代第一个不平等条约《中英南京条约》十三款：割让香港岛予英国，赔款二千一百万银元，开放广州、厦门、福州、宁波、上海五口通商，废除公行，英商进出口货税“秉公议定则例”（丧失关税自主权），中国开始沦为半殖民地半封建社会。同年冬魏源受林则徐嘱托编成《海国图志》五十卷本，首倡“师夷长技以制夷”。",
