          "detail": "三月（公历5月），日本明治政府借口同治十年琉球宫古岛船民漂流台湾南部被牡丹社排湾族误杀，命西乡从道率日军三千余人在台湾琅峤（恒春）登陆侵袭牡丹社；清廷急命船政大臣沈葆桢为钦差大臣率兵轮渡海赴台筹防增筑亿载金城，九月恭亲王奕訢与日使大久保利通签署《中日北京专约》，清廷给付“抚恤及修道建房费”白银五十万两换取日军撤台。台海危机与伊犁危机并起，十一月引发直隶总督李鸿章（倡暂弃新疆移饷专顾海防）与陕甘总督左宗棠（力陈“重新疆所以保蒙古，保蒙古所以卫京师”，主海塞并重）之“海防与塞防大论战”。十二月初五日甲戌（公历1875年1月12日）十九岁之同治帝载淳患天花崩，慈安、慈禧两宫太后择立醇亲王奕譞四岁幼子载湉入嗣咸丰帝即位（光绪帝），两宫再度垂帘听政。",
