          "detail": "正月日军水陆夹攻山东威海卫，刘公岛孤悬无援，定远舰管带刘步蟾、总兵杨用霖与提督丁汝昌拒绝劝降先后自尽殉国，正月二十三日（公历2月17日）日军占领刘公岛，北洋水师全军覆没。三月二十三日（公历4月17日），全权大臣李鸿章与日本首相伊藤博文、外相陆奥宗光于日本下关春帆楼签署《中日讲和条约》（《马关条约》）：承认朝鲜“完全无缺之独立自主”（废除中朝宗藩关系）；割让辽东半岛、台湾全岛及所有附属各岛屿、澎湖列岛予日本；赔偿军费白银二亿两；增开沙市、重庆、苏州、杭州四口岸，并首次允许日人在中国通商口岸任便设厂制造（帝国主义对华资本输出合法化）。旋俄、德、法三国出面迫日归还辽东半岛，清廷增付“赎辽费”白银三千万两（“三国干涉还辽”）。五月日军在台湾澳底登陆，台湾义军首领徐骧、吴汤兴、姜绍祖与留台抗日之黑旗军统领刘永福浴血抗击近五个月，毙伤日军数千人（日近卫师团长北白川宫能久亲王殒命于台南），悲壮谱写乙未保台史诗。",
