          "detail": "十二月初十日（公历1901年1月29日），流亡西安之慈禧太后以光绪帝名义颁布变法上谕，宣称“量中华之物力，结与国之欢心”的同时诏内外臣工条议改制（随后设督办政务处、废武科、改总理衙门为外务部班列六部之前），开启“清末新政”。七月二十五日（公历9月7日），全权大臣庆亲王奕劻、李鸿章与英、美、俄、德、日、奥、法、意、西、比、荷十一国驻华公使于北京正式签署《辛丑各国和约》（《辛丑条约》）：向各国赔偿白银四亿五千万两（按当时中国四亿五千万人口每人罚银一两计，分三十九年付清，本息合计逾九亿八千万两，以海关税、常关税和盐税作抵押，史称“庚子赔款”）；划定北京东交民巷为使馆界由各国驻兵管理、中国人概不准界内居住；拆毁大沽炮台及京津沿线炮台，允许各国驻兵北京至山海关铁路沿线十二处战略要地；永远禁止中国人民成立或加入任何反帝组织（违者斩，地方官革职永不叙用）。九月二十七日（公历11月7日）李鸿章卒于北京；《辛丑条约》标志清政府沦为列强统治中国之工具，中国完全陷入半殖民地半封建社会深渊。",
