          "detail": "八月初一日（公历8月27日），清廷颁布中国历史上首部宪法性文件《钦定宪法大纲》二十三条（正文“君上大权”十四条悉仿日本明治宪法而集权尤甚，规定“大清帝国万世一系，永永尊戴”，议院仅具协赞权），定预备立宪期限为九年。十月二十一日癸酉（公历11月14日）傍晚，幽禁瀛台涵元殿十载之三十八岁光绪帝载湉暴崩（清宫脉案称病逝，2008年国家清史纂修工程联合原子能科学研究院经中子活化刑侦检测证实光绪帝遗发与遗骨含致死量三氧化二砷即急性剧毒砒霜中毒身亡）；慈禧太后临终定立醇亲王载沣三岁长子溥仪入嗣同治帝兼祧光绪帝为帝，命载沣为监国摄政王，次日二十二日甲戌（公历11月15日）统治晚清四十七年之七十四岁慈禧太后叶赫那拉氏崩于仪鸾殿。十一月初九日壬辰（公历12月2日）幼帝溥仪于太和殿即位，诏以明年为宣统元年（十二月载沣以“足疾”罢黜军机大臣袁世凯回籍养疴）。",
