          "detail": "三月二十九日（公历4月27日），黄兴率同盟会海内外精英“选锋”百余人于广州奋勇攻入两广总督署，总督张鸣岐越墙逃遁，起义军与大批清军血战一昼夜终因众寡悬殊失败，林觉民（留绝笔《与妻书》）、方声洞、喻培伦等八十余人壮烈殉难，潘达微收殓其中七十二具遗骸合葬于广州东郊红花岗，改名“黄花岗七十二烈士”。四月初十日（公历5月8日），清廷裁军机处改设责任内阁，以庆亲王奕劻为总理大臣，十三名阁员中满族占九人、皇族亲贵竟占五人，舆论哗然斥为“皇族内阁”，立宪派彻底离心；次日清廷悍然宣布“铁路干线国有”政策，强夺商办川汉、粤汉铁路路权抵押予英、法、德、美四国银行团借款，激起湘、鄂、粤、川四省民众强烈反抗，四川保路同志会罢市罢课演为全省同志军武装起义，七月十五日（公历9月7日）川督赵尔丰诱捕蒲殿俊、罗伦并枪杀请愿民众数十人制造“成都血案”，清廷急调端方率湖北新军入川镇压，致使武昌兵力空虚。",
