          "detail": "湖北革命团体文学社（蒋翊武）与共进会（孙武）长期在湖北新军中秘密发展组织约占全军三分之一；八月十八日汉口宝善里配制炸弹失慎事泄，彭楚藩、刘复基、杨宏胜三烈士于十九日晨英勇就义。八月十九日（公历10月10日）夜，武昌工程第八营革命党人熊秉坤、金兆龙果断打响辛亥武昌首义第一枪，击毙排长夺占楚望台军械库，各标营新军群起响应猛攻湖广总督署，总督瑞澂凿墙逃登兵舰，一夜血战光复武昌，二十日成立“中华民国军政府鄂军都督府”（推黎元洪任都督，旋克汉阳、汉口合称阳夏光复）。武昌首义一声炮响震动寰宇，自九月初至十月短短月余，湘、陕、赣、晋、滇、黔、沪、浙、苏、桂、皖、粤、闽、川等十余省相继脱离清廷宣布独立，清廷惊惶起用袁世凯为内阁总理大臣统北洋军南下。十一月初十日（公历12月29日），十七省代表集会南京选举返国之孙中山为中华民国临时大总统，统治中国二百六十八年之清王朝土崩瓦解，绵延两千一百余年之君主专制帝制迎来覆灭前夜。",
